# Testo e scaletta visiva del video lungo (un'unica fonte per script.py e scenes.py)
# Caso 028: lo smemorato di Collegno, il caso Bruneri-Canella (Torino 1926 - Rio de Janeiro 1941)
SC = [
 # 00 INTRO
 (0, "Febbraio 1927. Un settimanale molto letto pubblica la foto di un uomo con la barba, sui quarantacinque anni. Non sa come si chiama, non sa da dove viene. Sotto la foto c'è una domanda: chi lo conosce?", [('Febbraio', 'cal:LA FOTO SUL GIORNALE|FEBBRAIO 1927'), ('foto', 'face:0'), ('quarantacinque', 'big:≈ 45 anni|età stimata · nessun nome'), ('domanda', 'h:Chi lo *conosce*?')]),
 (0, "Rispondono in due. Una signora di Verona dice: è mio marito, un professore di filosofia disperso nella Grande guerra. Una donna di Torino dice: è mio marito, un tipografo ricercato per truffa.", [('Rispondono', 'face:2'), ('Verona', 'i:woman|VERONA · «È MIO MARITO»'), ('Torino', 'i:woman2|TORINO · «È MIO MARITO»'), ('truffa', 'stamp:DUE MOGLI')]),
 (0, "Due mogli, due famiglie, due vite completamente diverse. E un solo uomo, che dice di non ricordare niente. Per anni l'Italia si divide, i tribunali decidono, e la storia diventa un modo di dire che usiamo ancora oggi: lo smemorato di Collegno.", [('Due', 'ii:two_claim|DUE FAMIGLIE|beard|UN SOLO UOMO'), ('tribunali', 'i:court|I TRIBUNALI'), ('modo', 'h:Lo smemorato\ndi *Collegno*')]),
 (0, "In questo fascicolo vedremo chi era davvero quell'uomo secondo i giudici, perché due famiglie lo hanno riconosciuto, cosa hanno detto le impronte digitali, come è finita in Brasile, e cosa ha aggiunto, quasi un secolo dopo, il DNA.", [('In', 'cover'), ('giudici', 'iii:court|I GIUDICI|finger|LE IMPRONTE|dnay|IL DNA'), ('Brasile', 't:IL CASO BRUNERI-CANELLA · 1926-1941')]),
 # 01 L'ITALIA DEI DISPERSI
 (1, "Per capire perché questa storia ha appassionato un paese intero, bisogna partire dalla guerra. Tra il 1915 e il 1918 l'Italia combatte la Prima guerra mondiale. Centinaia di migliaia di soldati non tornano a casa.", [('Per', 'tl:1915|L\'ITALIA IN GUERRA;1916|MACEDONIA;1921|IL MILITE IGNOTO;1926|IL CIMITERO;1927|LA FOTO'), ('1915', 'cal:LA GRANDE GUERRA|1915-1918'), ('Centinaia', 'crowd')]),
 (1, "Molti di loro sono morti in battaglia e sono stati sepolti. Ma tanti altri risultano soltanto dispersi. Vuol dire che nessuno ha visto con certezza cosa gli è successo. Non c'è un corpo, non c'è una tomba, non c'è un saluto.", [('Molti', 'i:grave|I CADUTI'), ('dispersi', 'stamp:DISPERSO'), ('corpo', 'iii:question|NESSUN CORPO|frame_empty|NESSUNA TOMBA|envelope|NESSUNA NOTIZIA')]),
 (1, "Per le famiglie dei dispersi, la guerra non finisce mai del tutto. C'è sempre una piccola speranza: che sia prigioniero da qualche parte, che sia ferito, che abbia perso la memoria e un giorno torni.", [('famiglie', 'fig:man|UNA FAMIGLIA CHE ASPETTA'), ('speranza', 'i:envelope|UNA LETTERA CHE NON ARRIVA'), ('memoria', 'face:0')]),
 (1, "Lo Stato prova a dare un volto a questo dolore. Nell'ottobre 1921, nella basilica di Aquileia, vengono messe in fila undici bare di soldati senza nome. Una madre che ha perso il figlio in guerra, Maria Bergamas, ne sceglie una.", [('Stato', 'i:ministry|LO STATO'), ('Aquileia', 'map:Verona|40|Aquileia'), ('undici', 'big:11 bare|soldati senza nome · Aquileia 1921'), ('Bergamas', 'fig:man|UNA MADRE')]),
 (1, "Quella bara viaggia in treno fino a Roma e il 4 novembre 1921 viene sepolta all'Altare della Patria, al Vittoriano. È il Milite Ignoto: un soldato sconosciuto che rappresenta tutti quelli che non sono tornati.", [('treno', 'i:train|VERSO ROMA'), ('4', 'cal:IL MILITE IGNOTO|4 NOVEMBRE 1921'), ('Vittoriano', 'i:museum|ALTARE DELLA PATRIA'), ('sconosciuto', 'stamp:IGNOTO')]),
 (1, "Tenete a mente questa parola, ignoto, perché tornerà. Cinque anni dopo, un uomo senza nome finirà in un manicomio vicino a Torino. E molte famiglie italiane guarderanno la sua foto chiedendosi: e se fosse lui?", [('ignoto', 'h:*Ignoto*'), ('Cinque', 'flow:1921 · IL MILITE IGNOTO>1926 · UN UOMO SENZA NOME'), ('foto', 'face:0'), ('fosse', 'stamp:E SE FOSSE LUI?')]),
 (1, "Ma il nostro disperso non è sparito sulle Alpi o sul Carso. È sparito molto più lontano: in Macedonia. Nel 1916 l'Italia manda in quella zona dei Balcani un corpo di spedizione, la trentacinquesima divisione.", [('disperso', 'i:helmet|UN DISPERSO'), ('Macedonia', 'map:Monastir|8|Verona,Monastir|Verona>Monastir'), ('1916', 'cal:IL FRONTE MACEDONE|1916'), ('trentacinquesima', 'card:35ª DIVISIONE|corpo di spedizione|fronte macedone · 1916')]),
 (1, "Partono nell'estate del 1916, per combattere a fianco degli alleati sul fronte macedone, nell'entroterra di Salonicco. È una guerra di montagne, lontana dai giornali e dalle grandi battaglie che tutti conoscono.", [('Partono', 'map:Salonicco|10|Salonicco,Monastir'), ('alleati', 'i:flagless_globe|CON GLI ALLEATI'), ('montagne', 'i:mountain|UNA GUERRA DI MONTAGNE')]),
 (1, "Facciamo un conto: tra Verona e Monastir, una delle città del fronte macedone, oggi Bitola, nella Macedonia del Nord, ci sono quasi mille chilometri in linea d'aria. Per una famiglia degli anni Dieci, un altro mondo.", [('conto', 'map:Monastir|8|Verona,Monastir|Verona>Monastir'), ('mille', "big:≈ 1.000 km|Verona - Monastir · in linea d'aria"), ('mondo', 'i:flagless_globe|UN ALTRO MONDO')]),
 (1, "Un'ultima cosa sul contesto. Negli anni Venti i giornali illustrati sono la televisione di allora. Il più famoso è la Domenica del Corriere, supplemento del Corriere della Sera nato nel 1899: per anni è il settimanale più venduto d'Italia.", [('contesto', 'i:newspaper|I GIORNALI ILLUSTRATI'), ('televisione', 'i:tv|LA TV DI ALLORA'), ('Domenica', 'card:LA DOMENICA DEL CORRIERE|settimanale illustrato|dal 1899'), ('venduto', 'big:N. 1|il settimanale più venduto')]),
 # 02 I PROTAGONISTI
 (2, "Prima di entrare nella storia, conosciamo i protagonisti. Al centro c'è lui: un uomo con la barba, sui quarantacinque anni, che nel 1926 viene registrato con un numero, perché un nome non ce l'ha.", [('Prima', 'board:0'), ('barba', 'face:0'), ('numero', 'i:beard_n|IL SUO NUMERO')]),
 (2, "Il primo candidato è Giulio Canella, professore di filosofia a Verona. È uno studioso cattolico stimato. Insieme a padre Agostino Gemelli, che in seguito fonderà l'Università Cattolica, è tra i fondatori di una rivista di filosofia neoscolastica.", [('primo', 'board:1'), ('filosofia', 'i:book|FILOSOFIA · VERONA'), ('Gemelli', 'card:PADRE AGOSTINO GEMELLI|collega di Canella|poi fondatore della Cattolica'), ('rivista', 'i:magazine|UNA RIVISTA DI FILOSOFIA')]),
 (2, "Canella ha sposato una cugina, Giulia. La famiglia di lei è benestante e il padre ha fatto fortuna con affari in Brasile. Un dettaglio che, alla fine di questa storia, diventerà decisivo.", [('Canella', 'board:2'), ('Giulia', 'i:woman|GIULIA CANELLA'), ('Brasile', 'map:Verona|4|Verona,Rio de Janeiro'), ('decisivo', 'stamp:DA RICORDARE')]),
 (2, "Poi Giulio parte per la guerra, verso il fronte macedone. Nel novembre 1916, durante una battaglia, sparisce. Nessuno lo vede morire. Per lo Stato è un disperso. Per la moglie, che non accetta la notizia, è un uomo che prima o poi tornerà.", [('Giulio', 'i:helmet|IL FRONTE MACEDONE'), ('1916', 'cal:DISPERSO|NOVEMBRE 1916'), ('disperso', 'doc:MINISTERO DELLA GUERRA|Canella Giulio|stato: DISPERSO|fronte macedone · 1916'), ('tornerà', 'i:house|L\'ATTESA')]),
 (2, "Il secondo candidato è Mario Bruneri, nato a Torino. Di mestiere fa il tipografo: compone le pagine da stampare con i caratteri di piombo. Ma ha anche dei precedenti per furto e per truffa.", [('secondo', 'board:3'), ('tipografo', 'i:press|TIPOGRAFO · TORINO'), ('precedenti', 'card:MARIO BRUNERI|precedenti per furto e truffa|Torino')]),
 (2, "Le sue condanne per truffa non le ha mai scontate fino in fondo. Dal 1922 non si trova più: è latitante, cioè ricercato dalla giustizia. A Torino ha una moglie, Rosa Negro, da cui si è separato, e un figlio.", [('condanne', 'i:gavel|CONDANNE NON SCONTATE'), ('1922', 'cal:LATITANTE|DAL 1922'), ('Rosa', 'board:4'), ('figlio', 'i:woman2|ROSA NEGRO · TORINO')]),
 (2, "A Torino vivono anche la madre di Mario e le sue sorelle, mentre il fratello Felice abita in provincia. Sono persone comuni, che di lui non hanno notizie da anni. Anche loro, come vedremo, avranno un ruolo.", [('madre', 'iii:woman|LA MADRE|woman2|LE SORELLE|nophoto|IL FRATELLO'), ('comuni', 'map:Torino|60|Torino'), ('ruolo', 'stamp:TESTIMONI')]),
 (2, "E infine ci sono i giudici. Questa storia passerà da un tribunale di Torino a una corte d'appello, poi alla Cassazione, poi a Firenze e di nuovo in Cassazione. In tutto, quasi cinque anni di cause.", [('infine', 'board:5'), ('tribunale', 'tl:TORINO|TRIBUNALE;TORINO|APPELLO;ROMA|CASSAZIONE;FIRENZE|APPELLO;ROMA|CASSAZIONE'), ('cinque', 'big:≈ 5 anni|di cause e sentenze')]),
 (2, "Riassumiamo. Un uomo senza nome. Da una parte un professore di Verona, disperso in guerra, con una moglie benestante. Dall'altra un tipografo di Torino, ricercato, con una moglie operaia. E in mezzo, una sola faccia.", [('Riassumiamo', 'face:3'), ('professore', 'i:book|IL PROFESSORE · VERONA'), ('tipografo', 'i:press|IL TIPOGRAFO · TORINO'), ('faccia', 'face:3')]),
 # 03 IL CIMITERO E IL MANICOMIO
 (3, "Torino, 10 marzo 1926. Siamo nel cimitero monumentale della città, nella parte riservata alle sepolture ebraiche. Il custode nota un uomo che si muove tra le tombe in modo strano.", [('Torino', 'cal:TORINO|10 MARZO 1926'), ('cimitero', 'i:cemetery|IL CIMITERO MONUMENTALE'), ('custode', 'fig:guard|IL CUSTODE')]),
 (3, "L'uomo ha qualcosa sotto il cappotto. Quando viene fermato, salta fuori un vaso di metallo, preso da una tomba. Le fonti non sono d'accordo sul materiale: alcune parlano di bronzo, altre di rame.", [('cappotto', 'i:question|COSA NASCONDE?'), ('vaso', 'i:vase|UN VASO DA UNA TOMBA'), ('materiale', 'ii:vase|BRONZO?|vase|RAME?')]),
 (3, "Un furto da poco, insomma. Ma è quello che succede dopo a essere strano. L'uomo non ha documenti in tasca. Quando gli chiedono come si chiama, non risponde. Sembra confuso, molto agitato.", [('furto', 'i:vase|UN FURTO DA POCO'), ('documenti', 'i:nophoto|NESSUN DOCUMENTO'), ('chiedono', 'i:question|«COME SI CHIAMA?»'), ('confuso', 'face:0')]),
 (3, "Addosso ha pochissimo. Tra le poche cose c'è una cartolina, firmata con il nome affettuoso di un bambino. È l'unico indizio su chi possa essere. E tornerà, più avanti, in un modo inaspettato.", [('Addosso', 'i:magnifier|POCHE COSE'), ('cartolina', 'i:postcard|UNA CARTOLINA'), ('bambino', 'stamp:FIRMATA DA UN BAMBINO'), ('indizio', 'i:question|L\'UNICO INDIZIO')]),
 (3, "Un dettaglio colpisce tutti quelli che lo incontrano: parla un italiano corretto, educato, quasi elegante. Non sembra il modo di parlare di un ladro di cimiteri.", [('dettaglio', 'i:mic|COME PARLA'), ('italiano', 'h:Un italiano\n*forbito*'), ('ladro', 'ii:vase|IL FURTO|book|IL LINGUAGGIO')]),
 (3, "La polizia gli prende le impronte digitali e scatta le foto segnaletiche. Le schede vengono mandate a Roma, all'archivio centrale, per un confronto con i pregiudicati schedati. Ma il risultato è negativo: nessuna corrispondenza.", [('polizia', 'i:camera|FOTO SEGNALETICHE'), ('impronte', 'i:finger|LE IMPRONTE'), ('Roma', 'map:Roma|10|Torino,Roma|Torino>Roma'), ('negativo', 'stamp:NESSUNA CORRISPONDENZA')]),
 (3, "Ricordatevi anche questo dettaglio, il primo confronto delle impronte che non trova nulla. Perché un anno dopo le stesse impronte racconteranno una storia completamente diversa.", [('Ricordatevi', 'i:finger|PRIMO CONFRONTO · 1926'), ('nulla', 'big:0|corrispondenze trovate nel 1926'), ('diversa', 'stamp:TORNERANNO')]),
 (3, "Invece del carcere, l'uomo viene mandato in manicomio. È il manicomio di Collegno, alle porte di Torino, ospitato nella grande Certosa reale. I malati di mente vengono trasferiti in quegli edifici dalla metà dell'Ottocento.", [('carcere', 'flow:CARCERE?>MANICOMIO'), ('Collegno', 'map:Torino|60|Torino,Collegno'), ('Certosa', 'i:asylum|LA CERTOSA DI COLLEGNO'), ("dell'Ottocento", 'cal:IL MANICOMIO|DALLA METÀ DELL\'800')]),
 (3, "Lì riceve un numero di matricola: quarantaquattromila centosettanta. I medici lo descrivono confuso, ansioso, molto depresso, e soprattutto senza memoria. Diventa, per tutti, lo sconosciuto di Collegno.", [('numero', 'i:beard_n|MATRICOLA N. 44170'), ('medici', 'i:chair_doc|LA CARTELLA CLINICA'), ('memoria', 'h:Senza\n*memoria*'), ('sconosciuto', 'stamp:SCONOSCIUTO')]),
 (3, "Resterà a Collegno per quasi un anno. Nessuno lo riconosce. Fino a quando la direzione del manicomio decide di tentare una strada nuova: mostrare la sua faccia a tutta Italia.", [('Collegno', 'i:asylum|QUASI UN ANNO'), ('Nessuno', 'i:question|NESSUNO LO RICONOSCE'), ('faccia', 'face:0')]),
 # 04 LA FOTO SUL GIORNALE
 (4, "Il 6 febbraio 1927 la foto dello sconosciuto esce sulla Domenica del Corriere. Una fotografia accompagnata da poche righe e da quella domanda: chi lo conosce?", [('6', 'cal:LA DOMENICA DEL CORRIERE|6 FEBBRAIO 1927'), ('foto', 'news:SETTIMANALE ILLUSTRATO|6 febbraio 1927|Chi lo\n*conosce*?|ricostruzione grafica · non è la pagina originale'), ('domanda', 'h:Chi lo *conosce*?')]),
 (4, "Il testo lo descrive come una persona colta e distinta, sui quarantacinque anni, che parla italiano correntemente ma non sa dire il suo nome, la sua casa, il suo mestiere.", [('testo', 'doc:CHI LO CONOSCE?|persona colta e distinta|età: circa 45 anni|nome: ignoto|mestiere: ignoto'), ('quarantacinque', 'big:≈ 45 anni|età stimata'), ('nome', 'face:0')]),
 (4, "Pensate a cosa significa, in quegli anni. Migliaia di famiglie hanno un disperso. Ogni settimana tantissime persone sfogliano quel giornale. E ora, dalla pagina, le guarda un uomo che potrebbe essere chiunque.", [('Pensate', 'crowd'), ('famiglie', 'i:house|FAMIGLIE CHE ASPETTANO'), ('sfogliano', 'i:newspaper|IL GIORNALE'), ('chiunque', 'face:0')]),
 (4, "È una specie di Chi l'ha visto, decenni prima della televisione. Con una differenza enorme: qui non si cerca una persona scomparsa. Si cerca la famiglia di una persona che c'è, ma che non sa chi è.", [('specie', 'i:tvlive|COME UNA TRASMISSIONE TV'), ('differenza', 'ii:question|UNO SCOMPARSO?|beard|UN UOMO SENZA NOME'), ('famiglia', 'stamp:CERCASI FAMIGLIA')]),
 (4, "E la famiglia arriva. Anzi, ne arrivano due. Ma non insieme. La prima a farsi avanti è quella del professore. Il fratello di Giulio Canella, che vive a Verona, guarda la foto e pensa di riconoscere suo fratello.", [('famiglia', 'face:1'), ('due', 'big:2|famiglie'), ('fratello', 'fig:suit|IL FRATELLO DEL PROFESSORE'), ('Verona', 'map:Verona|60|Verona')]),
 (4, "E per il fratello ci sono dettagli che corrispondono, anche se non tutto torna. Secondo alcune ricostruzioni, mancano segni particolari che il professore aveva. Ma il fratello, alla fine, si convince.", [('dettagli', 'i:magnifier|I DETTAGLI'), ('ricostruzioni', 'stamp:NON TUTTO TORNA'), ('convince', 'i:witness|«È LUI»')]),
 (4, "La notizia arriva alla moglie, Giulia. Più di dieci anni dopo la scomparsa del marito, ha davanti una possibilità che forse ha sempre sperato. Dal novembre 1916 al febbraio 1927 sono passati più di dieci anni.", [('notizia', 'i:woman|GIULIA CANELLA'), ('scomparsa', 'tl:1916|DISPERSO;1921|MILITE IGNOTO;1926|COLLEGNO;1927|LA FOTO'), ('dieci', 'big:10 anni e 3 mesi|dalla scomparsa alla foto')]),
 (4, "Prima di andare avanti: se questa storia ti sta prendendo, iscriviti a Fascicolo Italia. Ogni giorno raccontiamo un caso vero, con le fonti. E adesso, andiamo a Collegno.", [('Prima', 'subscribe'), ('Collegno', 'i:asylum|COLLEGNO')]),
 # 05 LA MOGLIE DI VERONA
 (5, "Il 27 febbraio 1927 Giulia Canella entra nel manicomio di Collegno. Ha viaggiato da Verona per vedere da vicino lo sconosciuto della foto. È il momento che aspetta da più di dieci anni.", [('27', 'cal:COLLEGNO|27 FEBBRAIO 1927'), ('Giulia', 'i:woman|GIULIA CANELLA'), ('Verona', 'map:Verona|50|Verona,Torino|Verona>Torino'), ('momento', 'face:1')]),
 (5, "Le ricostruzioni raccontano che il riconoscimento non è immediato. Servono più incontri. Ma alla fine Giulia non ha dubbi: quell'uomo è suo marito. E lui sembra a sua volta riconoscerla.", [('ricostruzioni', 'ii:woman|GIULIA|beard|LO SCONOSCIUTO'), ('incontri', 'iii:calendar_x|1° INCONTRO|calendar_x|2° INCONTRO|calendar_x|3° INCONTRO'), ('dubbi', 'stamp:È MIO MARITO')]),
 (5, "E la cartolina? Quella trovata in tasca al momento dell'arresto, firmata da un bambino? Per la famiglia Canella la spiegazione è semplice: l'ha scritta il loro figlio, per il padre.", [('cartolina', 'i:postcard|LA CARTOLINA'), ('bambino', 'i:question|CHI L\'HA SCRITTA?'), ('figlio', 'flow:LA CARTOLINA>IL FIGLIO DEI CANELLA')]),
 (5, "Ricordate il primo indizio? Era la cartolina. E ora sembra combaciare perfettamente con la storia del professore. Per molti giornali, il caso è risolto: il disperso è tornato.", [('Ricordate', 'i:postcard|IL PRIMO INDIZIO'), ('combaciare', 'face:1'), ('giornali', 'news:QUOTIDIANO|marzo 1927|Il disperso\n*è tornato*|ricostruzione grafica · non è la pagina originale')]),
 (5, "All'inizio di marzo l'uomo viene dimesso dal manicomio e affidato a Giulia. Lasciano Torino e vanno verso il Veneto e il lago di Garda, ospiti di amici e parenti. Una nuova vita sembra cominciare.", [('marzo', 'cal:DIMESSO|INIZIO MARZO 1927'), ('Torino', 'map:Verona|50|Torino,Desenzano,Padova|Torino>Desenzano'), ('vita', 'ii:woman|GIULIA|beard|IL «PROFESSORE»')]),
 (5, "Fermiamoci un momento. Pensiamo a come funziona un riconoscimento a vista dopo più di dieci anni. Una persona cambia: invecchia, ingrassa o dimagrisce, perde i capelli, si fa crescere la barba.", [('Fermiamoci', 'i:eye|IL RICONOSCIMENTO A VISTA'), ('dieci', 'big:10+ anni|di distanza'), ('invecchia', 'iii:beard|LA BARBA|hourglass|IL TEMPO|eye|LO SGUARDO')]),
 (5, "E chi guarda non è neutrale. Una moglie che aspetta da dieci anni vuole, comprensibilmente, che sia lui. Questo non vuol dire che sbagli. Vuol dire che il suo riconoscimento, da solo, non basta a dare una risposta certa.", [('neutrale', 'i:woman|CHI GUARDA'), ('aspetta', 'i:hourglass|DIECI ANNI DI ATTESA'), ('basta', 'stamp:NON BASTA')]),
 (5, "Lo scrittore Leonardo Sciascia, che ha dedicato al caso un racconto nel 1981, sta dalla parte di Giulia. La descrive come l'unica persona che ha creduto fino in fondo, senza mai vacillare.", [('Sciascia', 'card:LEONARDO SCIASCIA|«Il teatro della memoria»|1981'), ('racconto', 'i:oldbook|IL TEATRO DELLA MEMORIA'), ('creduto', 'stamp:SENZA DUBBI')]),
 (5, "Ma mentre Giulia e il presunto professore si godono i primi giorni insieme, a Torino succede qualcosa. Qualcuno ha visto quella foto sul giornale. E qualcuno pensa di sapere chi è davvero.", [('Giulia', 'ii:woman|IL VENETO|beard|IL «PROFESSORE»'), ('Torino', 'map:Torino|60|Torino'), ('qualcuno', 'i:anon|QUALCUNO SA')]),
 (5, "Prima di andare avanti, facciamo il punto. Il cimitero nel marzo 1926. Il manicomio e il numero. La foto sul giornale nel febbraio 1927. Il riconoscimento di Giulia. Fin qui, tutto porta al professore.", [('punto', 'tl:MAR 1926|IL CIMITERO;1926|IL NUMERO 44170;FEB 1927|LA FOTO;27 FEB|GIULIA'), ('professore', 'face:1')]),
 # 06 LA LETTERA ANONIMA
 (6, "Pochi giorni dopo che l'uomo ha lasciato Collegno, alla questura di Torino arriva una lettera anonima. Sulla data esatta le fonti non coincidono. Ma il contenuto sì.", [('Pochi', 'i:anon|UNA LETTERA ANONIMA'), ('questura', 'i:questura|LA QUESTURA DI TORINO'), ('fonti', 'stamp:DATA NON CONCORDE')]),
 (6, "La lettera dice che l'uomo che si fa chiamare professor Canella potrebbe essere un altro: Mario Bruneri, il tipografo torinese, pregiudicato e latitante da anni.", [('lettera', 'doc:LETTERA ANONIMA · 1927|«non è il prof. Canella»|«è Mario Bruneri»|tipografo · ricercato'), ('Bruneri', 'face:2'), ('latitante', 'i:handcuffs|LATITANTE')]),
 (6, "Chi l'ha scritta? Le fonti che abbiamo consultato non lo dicono. Ma la questura prende la segnalazione sul serio, e decide di verificare.", [('scritta', 'i:question|CHI L\'HA SCRITTA?'), ('consultato', 'i:envelope|MITTENTE: IGNOTO'), ('verificare', 'i:magnifier|LA VERIFICA')]),
 (6, "L'uomo viene riportato a Torino. Il viaggio di ritorno è il primo segnale che la nuova vita da professore sta per finire. In questura lo aspettano le persone che conoscevano Mario Bruneri.", [('riportato', 'map:Torino|50|Desenzano,Torino|Desenzano>Torino'), ('viaggio', 'i:train|RITORNO A TORINO'), ('questura', 'i:questura|IN QUESTURA')]),
 (6, "Arriva Rosa Negro, la moglie da cui Bruneri si era separato. Arrivano le sorelle di Mario. E arriva il figlio. Uno dopo l'altro, lo guardano.", [('Rosa', 'i:woman2|ROSA NEGRO'), ('sorelle', 'ii:woman|LE SORELLE|nophoto|IL FIGLIO'), ('guardano', 'face:2')]),
 (6, "E tutti dicono la stessa cosa: è lui, è Mario. Le sorelle riconoscono il fratello, il figlio riconosce il padre. E Rosa Negro riconosce in lui suo marito, Mario Bruneri.", [('tutti', 'i:witness|«È MARIO»'), ('sorelle', 'stamp:RICONOSCIUTO'), ('Rosa', 'i:woman2|«È MIO MARITO»')]),
 (6, "Ora abbiamo il paradosso completo. Due famiglie, due riconoscimenti, due nomi. A Verona dicono Giulio Canella, professore. A Torino dicono Mario Bruneri, tipografo. E lui continua a dire di non ricordare.", [('paradosso', 'face:3'), ('Verona', 'ii:woman|«GIULIO CANELLA»|woman2|«MARIO BRUNERI»'), ('ricordare', 'h:«Non\n*ricordo*»')]),
 (6, "C'è anche un'altra ricostruzione curiosa. Ricordate la cartolina firmata da un bambino? Anche Mario Bruneri ha un figlio. Quella cartolina, che sembrava una prova per i Canella, ora può essere letta in due modi.", [('cartolina', 'i:postcard|LA CARTOLINA'), ('figlio', 'ii:house|FIGLIO DEI CANELLA?|house|FIGLIO DI BRUNERI?'), ('due', 'stamp:DUE LETTURE')]),
 (6, "Il giorno 11 marzo 1927 l'Agenzia Stefani, la principale agenzia di stampa italiana dell'epoca, diffonde un comunicato. Lo sconosciuto viene definito un simulatore, identificato come Mario Bruneri.", [('giorno', 'cal:AGENZIA STEFANI|11 MARZO 1927'), ('comunicato', 'doc:COMUNICATO · 11 MARZO 1927|lo sconosciuto di Collegno|è un «simulatore»|identificato: Mario Bruneri'), ('simulatore', 'stamp:SIMULATORE?')]),
 (6, "Per lo Stato la questione sembra chiusa in meno di due settimane. Ma Giulia Canella non accetta. E con lei una parte dell'Italia. La battaglia, in realtà, è appena cominciata.", [('Stato', 'i:ministry|PER LO STATO: BRUNERI'), ('Giulia', 'i:woman|GIULIA NON ACCETTA'), ('battaglia', 'crowd')]),
 # 07 LE IMPRONTE
 (7, "Come si può dire chi è una persona, se la persona stessa non lo dice e i testimoni si contraddicono? Negli anni Venti la risposta più moderna ha un nome: impronte digitali.", [('Come', 'i:question|CHI È?'), ('testimoni', 'ii:woman|TESTIMONE A|woman2|TESTIMONE B'), ('impronte', 'i:finger|LE IMPRONTE DIGITALI')]),
 (7, "In Italia la polizia scientifica nasce nel 1902, quando il medico Salvatore Ottolenghi fonda a Roma la Scuola di polizia scientifica. Pochi anni dopo, a un congresso a Torino, viene presentato un sistema italiano per classificare le impronte.", [('Italia', 'cal:SCUOLA DI POLIZIA SCIENTIFICA|ROMA 1902'), ('Ottolenghi', 'card:SALVATORE OTTOLENGHI|medico|fonda la scuola nel 1902'), ('congresso', 'card:IL SISTEMA ITALIANO|classificare le impronte|presentato a Torino · 1906')]),
 (7, "L'idea è semplice: le creste della pelle dei polpastrelli formano disegni che non cambiano nel corso della vita, e che sono diversi da persona a persona. Le barbe crescono, i visi invecchiano. Le impronte no.", [('creste', 'i:finger|DISEGNI UNICI'), ('cambiano', 'h:Non *cambiano*'), ('barbe', 'ii:beard|LA BARBA CRESCE|finger|L\'IMPRONTA RESTA')]),
 (7, "Bruneri, per i suoi precedenti, era già stato fermato e detenuto per brevi periodi a Torino. E in quelle occasioni gli erano state prese le impronte. Erano nei registri delle carceri torinesi.", [('Bruneri', 'i:press|MARIO BRUNERI'), ('detenuto', 'i:prison|LE CARCERI DI TORINO'), ('registri', 'i:folder|IL REGISTRO')]),
 (7, "Le impronte dello sconosciuto, prese dopo il furto al cimitero, vengono confrontate con quelle di Bruneri. E il risultato, questa volta, è netto: coincidono.", [('impronte', 'i:finger|LE IMPRONTE DEL 1926'), ('confrontate', 'prints'), ('coincidono', 'stamp:COINCIDONO')]),
 (7, "Ma allora perché il primo confronto, nel 1926, non aveva trovato nulla? Secondo una ricostruzione, perché Bruneri era un truffatore comune e le sue impronte non erano state mandate all'archivio centrale di Roma. Le fonti non spiegano tutte allo stesso modo questo passaggio.", [('primo', 'big:0|corrispondenze nel 1926'), ('truffatore', 'ii:folder|TORINO: SÌ|folder|ROMA: NO'), ('fonti', 'stamp:VERSIONI DIVERSE')]),
 (7, "Le impronte non sono l'unico esame. Lo sconosciuto viene sottoposto a perizie psichiatriche. E un perito psichiatra conclude che la sua amnesia è simulata: secondo lui, finge di non ricordare per non finire in carcere.", [('impronte', 'i:finger|NON SOLO IMPRONTE'), ('perizie', 'i:chair_doc|LA PERIZIA'), ('simulata', 'stamp:AMNESIA SIMULATA?')]),
 (7, "Secondo le ricostruzioni, il perito è lo psichiatra Alfredo Coppola, che sul caso scriverà anche uno studio. La sua conclusione è netta: è Bruneri, e l'amnesia è finta. Secondo una ricostruzione, però, altri medici non erano d'accordo.", [('Coppola', 'card:ALFREDO COPPOLA|psichiatra|perito sul caso'), ('Bruneri', 'face:4'), ('medici', 'ii:chair_doc|«È SIMULATA»|question|«NON È DETTO»')]),
 (7, "E c'è un testimone pesante. Padre Agostino Gemelli, che aveva lavorato a lungo con il vero Giulio Canella, secondo le ricostruzioni dice che quell'uomo non è il suo collega.", [('testimone', 'i:witness|UN TESTIMONE PESANTE'), ('Gemelli', 'card:PADRE AGOSTINO GEMELLI|collega di Canella|«non è lui»'), ('collega', 'stamp:NON È CANELLA')]),
 (7, "Facciamo il punto. Per i Canella: la moglie, il fratello, la cartolina. Per i Bruneri: la moglie, le sorelle, il figlio, le impronte, la perizia, e il collega di Canella. Ora la parola passa ai giudici.", [('punto', 'face:4'), ('Canella', 'bars:CANELLA|3|BRUNERI|6'), ('giudici', 'i:court|LA PAROLA AI GIUDICI')]),
 # 08 I PROCESSI
 (8, "Partiamo da una cosa importante. Qui non si discute solo di un furto in un cimitero. La domanda è più grande: chi è questa persona per la legge? E da quella risposta dipende tutto il resto.", [('Partiamo', 'i:vase|NON SOLO UN FURTO'), ('legge', 'h:Chi è\nper la *legge*?'), ('tutto', 'iii:rings|IL MATRIMONIO|house|L\'EREDITÀ|bars|LE CONDANNE')]),
 (8, "Se è Canella, è un professore tornato dalla guerra, sposato con Giulia, padre dei suoi figli. Se è Bruneri, è un latitante che deve scontare vecchie condanne, sposato con un'altra donna. E la convivenza con Giulia diventa uno scandalo.", [('Canella', 'card:SE È CANELLA|professore tornato dalla guerra|marito di Giulia'), ('Bruneri', 'card:SE È BRUNERI|latitante con condanne|marito di Rosa Negro'), ('scandalo', 'stamp:SCANDALO')]),
 (8, "Nel gennaio 1928 Rosa Negro e altri familiari di Bruneri si rivolgono al tribunale per far stabilire che quell'uomo è Mario Bruneri. È una causa civile, cioè sull'identità della persona.", [('gennaio', 'cal:LA CAUSA|GENNAIO 1928'), ('Rosa', 'i:woman2|ROSA NEGRO'), ('civile', 'doc:CAUSA CIVILE · 1928|oggetto: identità|«è Mario Bruneri»')]),
 (8, "Dall'altra parte, la famiglia Canella si difende con avvocati importanti. Tra i difensori, secondo le ricostruzioni, c'è anche Francesco Carnelutti, uno dei giuristi più noti del Novecento.", [("Dall'altra", 'i:woman|LA DIFESA DEI CANELLA'), ('Carnelutti', 'card:FRANCESCO CARNELUTTI|giurista e avvocato|tra i difensori'), ('Novecento', 'i:scales|LA DIFESA')]),
 (8, "Il processo civile si apre a Torino il 22 ottobre 1928. Sfilano i testimoni. Parenti, amici, conoscenti, medici, colleghi. Ognuno porta un ricordo, un dettaglio, una certezza.", [('22', 'cal:TRIBUNALE DI TORINO|22 OTTOBRE 1928'), ('testimoni', 'crowd'), ('ricordo', 'i:witness|I TESTIMONI')]),
 (8, "Fuori dai tribunali, intanto, l'Italia si divide in due. C'è chi sta con Giulia Canella e chi sta con Rosa Negro. Lo scrittore Leonardo Sciascia ricorderà che da ragazzo, in Sicilia, sentiva fare scommesse sull'identità dello smemorato nei saloni dei barbieri e nei circoli.", [('Fuori', 'ii:woman|CON GIULIA|woman2|CON ROSA'), ('Sciascia', 'i:newspaper|SE NE PARLA OVUNQUE'), ('scommesse', 'stamp:CANELLA O BRUNERI?')]),
 (8, "E il tribunale di Torino decide, nello stesso 1928: l'uomo è Mario Bruneri. Le richieste della famiglia Canella vengono respinte. È la prima sentenza.", [('tribunale', 'court:1928 · «È BRUNERI»'), ('respinte', 'stamp:RESPINTO'), ('prima', 'tl:1928|TRIBUNALE: BRUNERI')]),
 (8, "Giulia Canella fa ricorso. Nel 1929, in appello, la decisione viene confermata: è Bruneri. Intanto, mentre le cause vanno avanti, la vita continua. Giulia e l'uomo vivono insieme come marito e moglie, e nascono dei figli.", [('ricorso', 'i:woman|IL RICORSO'), ('1929', 'tl:1928|TRIBUNALE: BRUNERI;1929|APPELLO: BRUNERI'), ('figli', 'i:house|LA VITA CONTINUA')]),
 (8, "Nello stesso 1929 muore la madre di Mario Bruneri. Non era stata messa a confronto con lui. Una delle tante domande che restano su questo caso: cosa avrebbe detto, guardandolo, la persona che lo aveva messo al mondo?", [('1929', 'cal:LA MADRE DI BRUNERI|1929'), ('confronto', 'i:question|NESSUN CONFRONTO'), ('mondo', 'stamp:UNA DOMANDA')]),
 (8, "Il caso arriva in Cassazione, a Roma. Sui passaggi intermedi le fonti non raccontano tutto allo stesso modo. Quello che è certo è che si arriva a un nuovo giudizio davanti alla Corte d'appello di Firenze.", [('Cassazione', 'i:court|CASSAZIONE · ROMA'), ('fonti', 'stamp:PASSAGGI NON CONCORDI'), ('Firenze', 'map:Firenze|40|Torino,Firenze,Roma')]),
 (8, "A maggio 1931 la Corte d'appello di Firenze stabilisce, ancora una volta, che lo sconosciuto di Collegno è Mario Bruneri. È la terza sentenza nello stesso senso.", [('maggio', 'cal:CORTE D\'APPELLO DI FIRENZE|MAGGIO 1931'), ('Bruneri', 'court:FIRENZE · «È BRUNERI»'), ('terza', 'tl:1928|TORINO;1929|TORINO;1931|FIRENZE')]),
 (8, "L'ultima parola tocca di nuovo alla Corte di Cassazione, che nel dicembre 1931 rende definitiva la decisione. Il giorno esatto non coincide tra le fonti. Ma il risultato sì: per la legge italiana, quell'uomo è Mario Bruneri.", [("L'ultima", 'cal:CASSAZIONE|DICEMBRE 1931'), ('giorno', 'stamp:GIORNO NON CONCORDE'), ('Bruneri', 'face:5')]),
 (8, "Mentre in tribunale si discute, a teatro va in scena una storia molto simile. Nel 1930 a Milano debutta Come tu mi vuoi, una commedia di Luigi Pirandello su un'identità contesa. Molti la collegano al caso di Collegno.", [('teatro', 'i:mask|A TEATRO'), ('1930', 'cal:«COME TU MI VUOI»|MILANO 1930'), ('Pirandello', 'card:LUIGI PIRANDELLO|«Come tu mi vuoi»|1930')]),
 (8, "Facciamo il conto. Dall'arresto al cimitero, nel marzo 1926, alla sentenza definitiva, nel dicembre 1931, passano quasi sei anni. Dalla foto sul giornale, quasi cinque. Per una domanda sola: chi sei?", [('conto', 'tl:MAR 1926|IL CIMITERO;FEB 1927|LA FOTO;1928|TORINO;1931|FIRENZE;DIC 1931|DEFINITIVA'), ('sei', 'big:≈ 6 anni|dal cimitero alla sentenza'), ('sei?', 'h:Chi *sei*?')]),
 # 09 COSA È SUCCESSO DOPO
 (9, "Con la sentenza definitiva, l'uomo deve scontare le condanne di Mario Bruneri. Viene mandato nel carcere di Pallanza, sul lago Maggiore, a poco più di cento chilometri da Torino.", [('sentenza', 'i:gavel|LA SENTENZA DEFINITIVA'), ('Pallanza', 'map:Torino|40|Torino,Pallanza|Torino>Pallanza'), ('cento', 'big:≈ 116 km|Torino - Pallanza · in linea d\'aria'), ('Torino', 'i:prison|IL CARCERE')]),
 (9, "Esce il primo maggio 1933, anche grazie a un'amnistia. In tutto, tra manicomio, carcere e attese, sono passati più di sette anni dal giorno del vaso al cimitero.", [('primo', 'cal:LIBERO|1° MAGGIO 1933'), ("un'amnistia", 'i:amnesty|L\'AMNISTIA'), ('sette', 'big:7 anni|dal cimitero alla libertà')]),
 (9, "E Giulia? Non ha mai cambiato idea. Appena l'uomo è libero, parte con lui e con i figli per il Brasile, dove il padre di lei aveva fatto fortuna. Ricordate quel dettaglio? Eccolo.", [('Giulia', 'i:woman|GIULIA NON CAMBIA IDEA'), ('Brasile', 'i:steam|VERSO IL BRASILE'), ('dettaglio', 'stamp:IL DETTAGLIO')]),
 (9, "Facciamo un ultimo conto di distanze. Tra Torino e Rio de Janeiro ci sono più di novemila chilometri in linea d'aria. Per l'Italia è Mario Bruneri. Dall'altra parte dell'oceano, può essere un'altra persona.", [('distanze', 'map:Rio de Janeiro|1|Torino,Rio de Janeiro|Torino>Rio de Janeiro'), ('novemila', "big:≈ 9.100 km|Torino - Rio · in linea d'aria"), ("dell'oceano", 'i:steam|OLTRE L\'OCEANO')]),
 (9, "In Brasile l'uomo vive come Giulio Canella. Scrive articoli e saggi di filosofia, tiene conferenze. È un professore, almeno per chi lo conosce lì. È un capitolo che in Italia sembra quasi impossibile da immaginare.", [('Brasile', 'i:rio|RIO DE JANEIRO'), ('articoli', 'iii:pen|ARTICOLI|book|SAGGI|mic|CONFERENZE'), ('professore', 'h:Il *professore*')]),
 (9, "Muore a Rio de Janeiro nel dicembre del 1941. Le fonti indicano il giorno 11 oppure il 12 dicembre. Viene sepolto con il nome di Giulio Canella. Dal cimitero di Torino al cimitero di Rio, sono passati quasi sedici anni.", [('Muore', 'cal:RIO DE JANEIRO|DICEMBRE 1941'), ('fonti', 'stamp:11 O 12 DICEMBRE'), ('sepolto', 'i:grave|«GIULIO CANELLA»'), ('sedici', 'big:≈ 16 anni|da Torino a Rio')]),
 (9, "Ma la storia non si ferma con la sua morte. I figli nati con Giulia portano un cognome che, per la legge italiana, non è il loro. E il dibattito sul caso continua per decenni.", [('storia', 'i:hourglass|LA STORIA CONTINUA'), ('cognome', 'h:Quale\n*cognome*?'), ('dibattito', 'i:folder|IL DIBATTITO CONTINUA')]),
 (9, "Nel 1970 arriva una presa di posizione inattesa. Una dichiarazione del Vaticano riconosce l'uomo come Giulio Canella, e i figli come legittimi. Lo Stato italiano invece non cambia la sua sentenza.", [('1970', 'cal:IL VATICANO|1970'), ('Vaticano', 'ii:convent|VATICANO: CANELLA|court|STATO: BRUNERI'), ('sentenza', 'stamp:LA SENTENZA RESTA')]),
 (9, "Intanto lo smemorato è entrato nella cultura italiana. Nel 1962 Sergio Corbucci gira il film Lo smemorato di Collegno, con Totò. Nel 2009 la Rai trasmette una fiction in due serate diretta da Maurizio Zaccaro.", [('cultura', 'i:film|NELLA CULTURA'), ('1962', 'card:«LO SMEMORATO DI COLLEGNO»|film · 1962|regia di Sergio Corbucci'), ('2009', 'cal:FICTION RAI|2009')]),
 (9, "La storica Lisa Roscioni ha pubblicato con Einaudi un libro che ricostruisce il caso, ed è da lì che è partita anche la fiction. E l'espressione smemorato di Collegno è ormai entrata nel linguaggio di tutti i giorni.", [('Roscioni', 'card:LISA ROSCIONI|«Lo smemorato di Collegno»|Einaudi'), ('fiction', 'i:film|LA FICTION'), ('linguaggio', 'h:«Sembri lo smemorato\ndi *Collegno*»')]),
 (9, "E il manicomio? Con la legge del 1978 che porta alla chiusura degli ospedali psichiatrici, anche Collegno cambia. Oggi in quegli edifici ci sono uffici dell'azienda sanitaria e un centro di documentazione sulla storia della psichiatria.", [('manicomio', 'i:asylum|COLLEGNO'), ('1978', 'cal:LA LEGGE 180|1978'), ('Oggi', 'iii:asylum|UFFICI SANITARI|folder|ARCHIVIO|library|DOCUMENTAZIONE')]),
 # 10 LE DOMANDE APERTE
 (10, "E ora le domande aperte. La prima è la più ovvia: i giudici avevano ragione? Per la legge italiana la risposta è definitiva dal 1931. Ma per una parte dell'opinione pubblica, il dubbio non è mai sparito.", [('domande', 'i:question|LE DOMANDE APERTE'), ('giudici', 'court:1931 · DEFINITIVA'), ('dubbio', 'face:3')]),
 (10, "Seconda domanda: si poteva fare un esame più sicuro delle impronte? Negli anni Venti no. Ma oggi esiste il DNA. E infatti, quasi un secolo dopo, qualcuno ci ha provato.", [('Seconda', 'i:finger|LE IMPRONTE · 1927'), ('DNA', 'i:dnay|IL DNA'), ('secolo', 'flow:1927 · IMPRONTE>2009-2014 · DNA')]),
 (10, "Nel 2009 la trasmissione Chi l'ha visto avvia un esame del DNA a partire da francobolli e lettere dell'epoca, consegnati dalla famiglia Canella. Ma quel primo tentativo non dà una risposta definitiva.", [('2009', 'cal:IL PRIMO TENTATIVO|2009'), ('francobolli', 'i:postcard|FRANCOBOLLI E LETTERE'), ('definitiva', 'stamp:NESSUNA RISPOSTA CERTA')]),
 (10, "Nel luglio 2014 ci si riprova. Una genetista confronta il DNA di un nipote del vero professore, discendente di un figlio nato prima della guerra, con quello di un figlio dello smemorato, nato dopo il suo ritorno.", [('luglio', 'cal:IL SECONDO TENTATIVO|LUGLIO 2014'), ('nipote', 'ii:dnay|NIPOTE DEL PROFESSORE|dnay|FIGLIO DELLO SMEMORATO'), ('ritorno', 'h:Stesso\n*padre*?')]),
 (10, "Il principio è semplice. Se lo smemorato fosse stato davvero Giulio Canella, i due discendenti per linea maschile avrebbero dovuto avere in comune una parte precisa del DNA, quella che passa di padre in figlio.", [('principio', 'i:dnay|DI PADRE IN FIGLIO'), ('maschile', 'flow:NONNO>NIPOTE'), ('figlio', 'stamp:IL CROMOSOMA Y')]),
 (10, "E il risultato? Qui le fonti non coincidono. Secondo le cronache di quei giorni, l'esame non conferma che fosse Canella. Secondo un'altra ricostruzione, il risultato preciso non è stato reso pubblico e il materiale poteva non bastare.", [('risultato', 'i:question|IL RISULTATO?'), ('cronache', 'card:VERSIONE 1|«non conferma»|che fosse Canella'), ('ricostruzione', 'card:VERSIONE 2|risultato non reso pubblico|materiale forse insufficiente')]),
 (10, "Il nipote del professore, aprendo la busta, ha commentato che non era il risultato che si aspettava. Una frase che dice molto, ma che non chiude formalmente il caso con una prova pubblicata.", [('nipote', 'i:envelope|LA BUSTA'), ('aspettava', 'h:«Non è il risultato\nche mi *aspettavo*»'), ('pubblicata', 'stamp:NESSUNA PROVA PUBBLICATA')]),
 (10, "Terza domanda: perché Giulia ci ha creduto fino alla fine? Amore, speranza, convinzione sincera? Possiamo solo ipotizzare. Quello che sappiamo è che non ha mai cambiato versione, né in tribunale né dopo.", [('Terza', 'i:woman|GIULIA'), ('Amore', 'iii:rings|AMORE?|hourglass|SPERANZA?|eye|CONVINZIONE?'), ('versione', 'stamp:MAI CAMBIATA')]),
 (10, "Anche il corpo dell'uomo è stato letto in modi opposti. Secondo una ricostruzione, una cicatrice sulla schiena corrispondeva a un'operazione subita dal professore. Secondo un'altra, mancavano invece dei segni particolari che il professore aveva. Le versioni, ancora una volta, non coincidono.", [('corpo', 'face:3'), ('cicatrice', 'card:PER I CANELLA|una cicatrice|che corrisponde'), ("un'altra", 'card:PER GLI ALTRI|segni particolari|che mancano'), ('versioni', 'stamp:VERSIONI OPPOSTE')]),
 (10, "Per chi ci ha raggiunto adesso, facciamo il punto. Il furto al cimitero nel 1926. La foto nel 1927. Due famiglie, le impronte, le sentenze fino al 1931. Il Brasile, la morte nel 1941. E il DNA, nel 2014.", [('punto', 'tl:1926|IL CIMITERO;1927|LA FOTO;1931|LE SENTENZE;1941|RIO;2014|IL DNA'), ('DNA', 'i:dnay|2014')]),
 (10, "E l'ultima domanda è quella che ha fatto discutere Sciascia e Pirandello: cosa ci rende quello che siamo? Il nome sui documenti? Il ricordo degli altri? O la vita che scegliamo di vivere?", [("l'ultima", 'ii:oldbook|SCIASCIA|mask|PIRANDELLO'), ('nome', 'iii:passport|I DOCUMENTI|witness|GLI ALTRI|house|LA VITA'), ('vivere', 'face:3')]),
 # 11 LA LEZIONE
 (11, "E arriviamo alla lezione. Questa storia ha cento anni, ma ci dice qualcosa di molto attuale: riconoscere una persona è più difficile di quanto pensiamo. Vediamo cinque idee semplici.", [('lezione', 'i:magnifier|LA LEZIONE'), ('riconoscere', 'i:eye|RICONOSCERE'), ('cinque', 'check:1')]),
 (11, "Prima idea: la memoria dei testimoni è preziosa, ma fragile. Nel caso di Collegno, persone sincere hanno riconosciuto con certezza due uomini diversi nella stessa faccia. Un riconoscimento a vista, da solo, non è una prova.", [('Prima', 'check:1'), ('testimoni', 'ii:woman|«È CANELLA»|woman2|«È BRUNERI»'), ('prova', 'stamp:NON È UNA PROVA')]),
 (11, "Seconda idea: le prove oggettive contano. Nel 1927 erano le impronte digitali. Oggi ci sono anche le analisi del DNA. Sono strumenti che non dipendono da quello che speriamo di vedere.", [('Seconda', 'check:2'), ('impronte', 'ii:finger|1927 · IMPRONTE|dnay|OGGI · DNA'), ('speriamo', 'h:Non dipendono\nda chi *guarda*')]),
 (11, "Terza idea: diffidare di chi si presenta come qualcun altro. Mario Bruneri, secondo i giudici, era un truffatore. Oggi il furto di identità passa soprattutto online: account falsi, messaggi che sembrano di un parente, profili rubati.", [('Terza', 'check:3'), ('truffatore', 'i:press|IL TRUFFATORE · SECONDO I GIUDICI'), ('online', 'iii:phone|MESSAGGI|nophoto|PROFILI FALSI|lock|ACCOUNT RUBATI')]),
 (11, "Se qualcuno ti scrive dicendo di essere un familiare con un numero nuovo e ti chiede soldi, verifica sempre con una chiamata al numero che già conosci. È la versione moderna di una lettera anonima: va controllata.", [('scrive', 'i:phone|«SONO IO, NUMERO NUOVO»'), ('verifica', 'i:shield_ok|VERIFICA SEMPRE'), ('anonima', 'i:anon|VA CONTROLLATA')]),
 (11, "Quarta idea: rispetto. Dietro ogni caso come questo ci sono famiglie vere: una moglie che aspetta un marito disperso, figli che crescono con un cognome contestato. Raccontare queste storie significa farlo con attenzione.", [('Quarta', 'check:4'), ('famiglie', 'i:two_claim|LE FAMIGLIE'), ('attenzione', 'i:house|LE FAMIGLIE')]),
 (11, "Quinta idea: le sentenze si rispettano, ma si possono raccontare anche i dubbi, distinguendo sempre tra quello che è stato deciso e quello che resta un'opinione. È quello che abbiamo provato a fare in questo fascicolo.", [('Quinta', 'check:5'), ('sentenze', 'court:LA SENTENZA'), ("un'opinione", 'ii:gavel|DECISO|question|OPINIONE')]),
 (11, "Le cinque idee, in breve: la memoria può ingannare, contano le prove oggettive, attenzione a chi si spaccia per un altro, rispetto per le famiglie, e distinguere i fatti dalle opinioni. Sono indicazioni generali, non una consulenza legale.", [('cinque', 'check:5'), ('generali', 't:INDICAZIONI GENERALI · NON CONSULENZA LEGALE')]),
 # IL VERDETTO
 (12, "Siamo al verdetto. Primo: nel marzo 1926 un uomo senza nome viene fermato in un cimitero di Torino mentre ruba un vaso, e finisce nel manicomio di Collegno con il numero quarantaquattromila centosettanta.", [('verdetto', 'i:gavel|IL VERDETTO'), ('Primo', 'i:vase|TORINO · 1926'), ('Collegno', 'i:beard_n|COLLEGNO')]),
 (12, "Secondo: nel 1927 la sua foto esce sul giornale, e due famiglie lo riconoscono. Per Giulia Canella è il marito professore, disperso nel 1916. Per Rosa Negro e i parenti è Mario Bruneri, tipografo e latitante.", [('Secondo', 'face:3'), ('Canella', 'ii:woman|CANELLA|woman2|BRUNERI')]),
 (12, "Terzo: le impronte digitali coincidono con quelle di Bruneri, e i giudici, fino alla Cassazione nel 1931, dicono la stessa cosa: è Bruneri. Quarto: sconta le condanne e nel 1933 torna libero.", [('Terzo', 'prints'), ('Cassazione', 'court:1931 · «È BRUNERI»'), ('Quarto', 'cal:LIBERO|1933')]),
 (12, "Quinto: parte con Giulia per il Brasile, dove vive come Giulio Canella fino alla morte, nel 1941. Sesto: quasi un secolo dopo, un esame del DNA in tv non conferma che fosse Canella, anche se le versioni sul risultato non coincidono del tutto.", [('Quinto', 'i:rio|RIO DE JANEIRO · 1941'), ('Sesto', 'i:dnay|IL DNA · 2014')]),
 (12, "E ora la domanda per te: se fossi stato un giudice nel 1931, ti saresti fidato delle impronte o delle persone che dicevano di riconoscerlo? Scrivilo nei commenti.", [('domanda', 'ii:finger|LE IMPRONTE?|witness|LE PERSONE?'), ('commenti', 'i:letter|SCRIVILO NEI COMMENTI')]),
 (12, "Iscriviti a Fascicolo Italia: ogni giorno un nuovo caso.", [('Iscriviti', 'subscribe')]),
]
